import logo from './logo.jpg';
import { FaSearch, FaShoppingCart } from 'react-icons/fa';
import { useNavigate } from "react-router-dom";
import { useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

const Menu = () => {
    const navigate = useNavigate();
    const [search, setSearch] = useState("");

    return (
        <nav className="navbar bg-white shadow-sm" style={{ padding: "6px 0" }}>
            <div className="container d-flex justify-content-center">
                <div className="d-flex align-items-center gap-3 flex-wrap" style={{ maxWidth: "1100px" }}>
                    {/* Logo */}
                    <a href="/home" className="me-3">
                        <img src={logo} alt="Logo" height="35" />
                    </a>

                    {/* Menu Links */}
                    <a className="text-dark text-decoration-none" href="/about-us">Về chúng tôi</a>
                    <a className="text-dark text-decoration-none" href="/blog">Blog</a>

                    {/* Dropdown */}
                    <div className="dropdown">
                        <a className="text-dark text-decoration-none dropdown-toggle" href="#" data-bs-toggle="dropdown">
                            Sản phẩm
                        </a>
                        <ul className="dropdown-menu">
                            <li><a className="dropdown-item" href="/men">Đồ Nam</a></li>
                            <li><a className="dropdown-item" href="/women">Đồ Nữ</a></li>
                            <li><a className="dropdown-item" href="/kids">Trẻ Em</a></li>
                        </ul>
                    </div>

                    <a className="text-dark text-decoration-none" href="/new-arrivals">Hàng mới về</a>

                    {/* Search box */}
                    <form className="d-flex align-items-center" onSubmit={(e) => e.preventDefault()}>
                        <input
                            className="form-control form-control-sm me-2"
                            type="search"
                            placeholder="Tìm kiếm..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            style={{ width: "140px" }}
                        />
                        <button className="btn btn-outline-secondary btn-sm" type="submit">
                            <FaSearch />
                        </button>
                    </form>

                    {/* Auth buttons */}
                    <button className="btn btn-outline-primary btn-sm" onClick={() => navigate("/login")}>
                        Đăng nhập
                    </button>
                    <button className="btn btn-primary btn-sm" onClick={() => navigate("/register")}>
                        Đăng ký
                    </button>

                    {/* Cart */}
                    <button className="btn btn-outline-dark btn-sm" onClick={() => navigate("/giohang")}>
                        <FaShoppingCart />
                    </button>
                </div>
            </div>
        </nav>
    );
};

export default Menu;
